import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { CtxDetail, QuotaBar } from '../types'

import {
  DEFAULTS,
  FIVE,
  WEEK,
  blocksAutomation,
  describeWindow,
  fmtClock,
  fmtDur,
  initialState,
  needsHeartbeat,
  statusLine,
  step,
} from './core'
import type { Config, Ev, Fx, State, Usage, Win } from './core'

const HEARTBEAT_MS = 30_000
const USER_KINDS = ['composer', 'bridge', 'sdk', 'slack-ping']
const PREFIX = 'quota-guard: '
const bar = atom({ plugin: 'quota-guard', key: 'bar' } as const, null)
const detail = atom({ plugin: 'quota-guard', key: 'detail' } as const, null)
const PANE = 'quota-ctx'

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const when = (w: Win | undefined, now: number) => {
  if (!w?.resetsAt || w.resetsAt <= now) return undefined
  return w.resetsAt - now > 20 * 3600_000 ? `${DAYS[new Date(w.resetsAt).getDay()]} ${fmtClock(w.resetsAt)}` : fmtClock(w.resetsAt)
}
const tok = (n?: number) => (n === undefined ? '' : n >= 1_000_000 ? `${(n / 1e6).toFixed(1)}M` : `${Math.round(n / 1000)}k`)
const CELLS = 10
const filled = (pct: number) => Math.max(0, Math.min(CELLS, Math.round((pct / 100) * CELLS)))
const fmtTok = (n: number) => (n >= 1_000_000 ? `${(n / 1e6).toFixed(2)}M` : n >= 10_000 ? `${Math.round(n / 1000)}k` : n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(Math.round(n)))
const tail = (path: string) => path.split(/[\\/]/).slice(-2).join('/')

function buildDetail(b: any, api: any): CtxDetail {
  const win = b.rawMaxTokens || b.maxTokens || 1
  const mcp = new Map<string, number>()
  for (const t of b.mcpTools ?? []) mcp.set(t.serverName, (mcp.get(t.serverName) ?? 0) + (t.isLoaded ? t.tokens : 0))
  return {
    model: b.model,
    total: b.totalTokens,
    window: win,
    percent: b.percentage,
    autoAt: b.isAutoCompactEnabled ? b.autoCompactThreshold : undefined,
    categories: (b.categories ?? []).map((c: any) => ({ name: c.name, tokens: c.tokens, kind: c.kind })),
    memory: (b.memoryFiles ?? []).map((m: any) => ({ path: tail(m.path), tokens: m.tokens })).sort((x: any, y: any) => y.tokens - x.tokens).slice(0, 8),
    mcp: [...mcp.entries()].map(([server, tokens]) => ({ server, tokens })).sort((x, y) => y.tokens - x.tokens).slice(0, 8),
    agents: (b.agents ?? []).map((a: any) => ({ name: a.agentType, tokens: a.tokens })).sort((x: any, y: any) => y.tokens - x.tokens).slice(0, 6),
    skills: b.skills ? { count: b.skills.includedSkills ?? b.skills.totalSkills, total: b.skills.totalSkills, tokens: b.skills.tokens, top: (b.skills.skillFrontmatter ?? []).map((k: any) => ({ name: k.name, tokens: k.tokens })).sort((x: any, y: any) => y.tokens - x.tokens).slice(0, 6) } : undefined,
    api: api ? { input: api.input_tokens, cacheRead: api.cache_read_input_tokens, cacheWrite: api.cache_creation_input_tokens, output: api.output_tokens } : undefined,
  }
}

// one distinct colour per category, assigned by size rank so the bar and the list always agree
const PALETTE = ['green', 'cyan', 'yellow', 'magenta', 'red', 'blue', 'white']
const colorAt = (rank: number) => PALETTE[rank % PALETTE.length] ?? 'white'
// Continuous bar: each segment is as wide as its share of the whole window, so the
// filled part is always exactly the context percentage. Segments are sized in cells
// (fractions allowed; the engine refuses fractional percentages).
// Remote surfaces (desktop, editor, mobile) can draw vectors: a rounded pill with a soft
// track, segments clipped to it, and a hairline where compaction starts to apply.
const HEX = ['#3fb950', '#22b8cf', '#e3b341', '#c678dd', '#f0626b', '#5b8def', '#adb5bd']
const hexAt = (rank: number) => HEX[rank % HEX.length] ?? '#adb5bd'

function ctxPill(Svg: any, segs: { pct: number; hex: string }[], w: number, bh: number, tickPct?: number) {
  const pad = 2
  const H = bh + pad * 2
  let x = 0
  const bars = segs
    .filter(sg => sg.pct > 0)
    .map(sg => {
      const sw = Math.max(0, Math.min(w - x, (sg.pct / 100) * w))
      const out = `<rect x="${x.toFixed(2)}" y="${pad}" width="${sw.toFixed(2)}" height="${bh}" fill="${sg.hex}"/>`
      x += sw
      return out
    })
    .join('')
  const tickMark = tickPct && tickPct > 0 && tickPct < 100 ? `<rect x="${((tickPct / 100) * w - 0.6).toFixed(2)}" y="0" width="1.2" height="${H}" rx="0.6" fill="#8b949e" opacity="0.85"/>` : ''
  const source =
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${H}" viewBox="0 0 ${w} ${H}">` +
    `<defs><clipPath id="p"><rect x="0" y="${pad}" width="${w}" height="${bh}" rx="${bh / 2}"/></clipPath></defs>` +
    `<rect x="0" y="${pad}" width="${w}" height="${bh}" rx="${bh / 2}" fill="#8b949e" fill-opacity="0.28"/>` +
    `<g clip-path="url(#p)">${bars}</g>${tickMark}</svg>`
  return <Svg source={source} alt="Context window usage" width={w} height={H} />
}

function swatch(Svg: any, hex: string) {
  return (
    <Svg
      source={`<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 10 10"><rect width="10" height="10" rx="3" fill="${hex}"/></svg>`}
      alt="category colour"
      width={10}
      height={10}
    />
  )
}

function ctxBar(Box: any, segs: { pct: number; color: string }[], width: number) {
  return (
    <Box width={width} height={1} flexShrink={0} backgroundColor="gray">
      {segs
        .filter(x => x.pct > 0)
        .map(x => (
          <Box width={Math.max(0, Math.min(width, (x.pct / 100) * width))} height={1} flexShrink={0} backgroundColor={x.color} />
        ))}
    </Box>
  )
}

const tone = (pct: number) => (pct >= 90 ? 'red' : pct >= 70 ? 'yellow' : 'green')

type Sim = {
  five: { percent: number; resetsAt: number }
  week?: { percent: number; resetsAt: number }
  mode: 'ok' | 'fail' | 'delay'
  failedOnce: boolean
  probeFails: number
  unavailable: boolean
  ctx?: number
}

type Overrides = Partial<Config> & { testMode?: boolean; dryActions?: boolean; legend?: boolean }

let S: State | null = null
let cfg: Config = { ...DEFAULTS }
let testMode = false
let dryActions = true
let legend = false
let sim: Sim | null = null
let sid = ''
let turnId: string | undefined
let timer: { cancel: () => void } | undefined
let loading: Promise<void> | undefined
let lastText = ''
let warned = false
let booted = false
const STAGGER_MS = 20_000
const MAX_STAGGER_MS = 120_000

let commandReady = false
async function registerCommand($: any) {
  if (commandReady) return
  const spec = {
    description: 'Quota guard: status, on/off, threshold, pause, cancel, resume, test',
    argumentHint: '[status|on|off|threshold N|weekly N|ctxmin N|ctx [close]|pause [min]|cancel|resume|test on|off|sim ...]',
    immediate: true as const,
  }
  try {
    await $.command.register({ name: 'quota', ...spec })
    await $.command.register({ name: 'quota-guard', ...spec })
    commandReady = true
  } catch (err) {
    $.ui.log(PREFIX + `could not register /quota: ${String(err)}`)
  }
}

let options: Readonly<Record<string, string | number | boolean | readonly string[]>> = {}
const num = (k: string, d: number) => (typeof options[k] === 'number' ? (options[k] as number) : d)

async function load($: any): Promise<void> {
  await registerCommand($)
  sid = await $.session.id()
  const saved = (await $.store.get('state:' + sid)) as State | undefined
  S = saved && saved.v === 1 ? saved : initialState()
  const o = ((await $.store.get('cfg')) ?? {}) as Overrides
  cfg = {
    enabled: typeof options.enabled === 'boolean' ? options.enabled : DEFAULTS.enabled,
    threshold: num('threshold', DEFAULTS.threshold),
    weeklyThreshold: num('weeklyThreshold', DEFAULTS.weeklyThreshold),
    abortThreshold: num('abortThreshold', DEFAULTS.abortThreshold),
    ceiling: DEFAULTS.ceiling,
    burnMultiplier: DEFAULTS.burnMultiplier,
    graceSec: num('graceSeconds', DEFAULTS.graceSec),
    maxResumeAttempts: num('maxResumeAttempts', DEFAULTS.maxResumeAttempts),
    weeklyPolicy: options.weeklyPolicy === 'notify' ? 'notify' : 'pause',
    notifyAt: num('notifyAt', DEFAULTS.notifyAt),
    compactMinContext: num('compactMinContext', DEFAULTS.compactMinContext),
  }
  testMode = typeof options.testMode === 'boolean' ? options.testMode : false
  const { testMode: tm, dryActions: da, legend: lg, ...rest } = o
  cfg = { ...cfg, ...rest }
  if (typeof tm === 'boolean') testMode = tm
  if (typeof da === 'boolean') dryActions = da
  if (typeof lg === 'boolean') legend = lg
  sim = ((await $.store.get('sim')) as Sim | undefined) ?? null
}

// A failure in this mod must never stop prompts or tool calls: hooks catch, log once, and pass through.
function logOnce($: any, err: unknown) {
  if (warned) return
  warned = true
  try {
    $.ui.log(PREFIX + `internal error, passing through: ${String(err)}`)
  } catch {
    /* nothing more to do */
  }
}

async function usable($: any): Promise<boolean> {
  try {
    await ensure($)
    return true
  } catch (err) {
    logOnce($, err)
    return false
  }
}

// Headless runs (claude -p, an SDK host with no UI) have no surface attached: never pause those,
// nobody would be there to resume them. Fails open to "watched" when the engine cannot say.
async function watched($: any): Promise<boolean> {
  try {
    return (await $.session.surfaces()).length > 0
  } catch {
    return true
  }
}

// Every open session shares the same account windows, so they all pause and wake together.
// Resume prompts are staggered through the shared store so they do not land in one burst.
async function claimSlot($: any) {
  try {
    const now = await $.clock.now()
    const last = Number(await $.store.get('lastResume')) || 0
    let h = 0
    for (const ch of sid) h = (h * 31 + ch.charCodeAt(0)) % 10
    const at = Math.min(Math.max(now + h * 1000, last + STAGGER_MS), now + MAX_STAGGER_MS)
    await $.store.set('lastResume', at)
    if (at > now) await $.clock.sleep(at - now)
  } catch {
    /* staggering is best effort */
  }
}


function ensure($: any): Promise<void> {
  if (!commandReady) void registerCommand($)
  if (S) return Promise.resolve()
  loading ??= load($).catch(err => {
    loading = undefined
    throw err
  })
  return loading
}

const persist = ($: any) => $.store.set('state:' + sid, S).catch(() => {})
const saveCfg = ($: any) =>
  $.store.set('cfg', { ...cfg, testMode, dryActions, legend }).catch(() => {})
const saveSim = ($: any) => $.store.set('sim', sim).catch(() => {})

// ---------- usage ----------

function simUsage(now: number, probing: boolean): Usage | null {
  if (!sim || sim.unavailable) return null
  const f = sim.five
  if (sim.mode === 'delay' && probing && sim.probeFails > 0) {
    sim.probeFails--
    f.percent = 100
    f.resetsAt = now + 120_000
  } else if (f.resetsAt <= now && !(sim.mode === 'delay' && sim.probeFails > 0)) {
    if (sim.mode === 'fail' && !sim.failedOnce) {
      sim.failedOnce = true
      f.resetsAt = now + 120_000
    } else if (sim.mode !== 'fail' || sim.failedOnce) {
      f.percent = 3
      f.resetsAt = now + 5 * 3600_000
    }
  }
  const windows: Win[] = [{ kind: FIVE, percent: f.percent, resetsAt: f.resetsAt }]
  if (sim.week) windows.push({ kind: WEEK, percent: sim.week.percent, resetsAt: sim.week.resetsAt })
  return { windows, contextPercent: sim.ctx }
}

function mapUsage(u: any): Usage {
  const windows: Win[] = (u.rateLimits ?? []).map((r: any) => ({
    kind: r.kind,
    percent: r.percentUsed,
    resetsAt: r.resetsAt ? Date.parse(r.resetsAt) : undefined,
  }))
  return { windows, contextPercent: u.context?.percent }
}

async function readUsage($: any): Promise<Usage | null> {
  try {
    if (testMode) {
      const u = simUsage(await $.clock.now(), S?.rec.phase === 'resuming')
      if (u && u.contextPercent === undefined) {
        try {
          u.contextPercent = (await $.session.usage()).context?.percent
        } catch {
          /* none */
        }
      }
      return u
    }
    const u = mapUsage(await $.session.usage())
    return u.windows.length ? u : null
  } catch {
    return null
  }
}

async function publish($: any, usage: Usage | null, now: number) {
  const st = S as State
  const five = usage?.windows.find(w => w.kind === FIVE)
  const week = usage?.windows.find(w => w.kind === WEEK)
  const rst = (w?: Win) => (w?.resetsAt && w.resetsAt > now ? fmtDur(w.resetsAt - now) : undefined)
  let ctx = usage?.contextPercent
  let ctxTokens: number | undefined
  let ctxWindow: number | undefined
  let parts: QuotaBar['parts'] = []
  try {
    const b = (await $.session.usage({ breakdown: 'summary' })).context
    ctx ??= b.percent ?? b.breakdown?.percentage
    ctxTokens = b.tokens ?? b.breakdown?.totalTokens
    ctxWindow = b.breakdown?.rawMaxTokens ?? b.window
    const bd = b.breakdown
    if (bd) await update($, detail, () => buildDetail(bd, bd.apiUsage))
    if (bd && bd.rawMaxTokens > 0) {
      parts = bd.categories
        .filter((c: any) => c.kind === 'used' && c.tokens > 0)
        .map((c: any) => ({ name: c.name, pct: (c.tokens / bd.rawMaxTokens) * 100 }))
        .sort((a: { pct: number }, c: { pct: number }) => c.pct - a.pct)
    }
  } catch {
    /* breakdown is cosmetic */
  }
  const v: QuotaBar = {
    ctx,
    parts,
    legend,
    ctxTokens,
    ctxWindow,
    five: five?.percent,
    fiveReset: rst(five),
    fiveAt: when(five, now),
    week: week?.percent,
    weekReset: rst(week),
    weekAt: when(week, now),
    threshold: cfg.threshold,
    ctxMin: cfg.compactMinContext,
    phase: st.rec.phase,
    note:
      st.rec.phase === 'paused' && st.rec.wakeAt
        ? `paused until ${fmtClock(st.rec.wakeAt)}`
        : usage ? undefined : 'waiting for first usage reading',
  }
  await update($, bar, () => v)
}

// ---------- dispatch / effects ----------

async function dispatch($: any, ev: Ev): Promise<void> {
  await ensure($)
  if ((ev.type === 'measure' || ev.type === 'tick' || ev.type === 'forcePause') && !(await watched($))) return
  const { state, fx } = step(S as State, ev, cfg)
  S = state
  await persist($)
  sync($)
  for (const f of fx) if (f.t === 'toast') say($, f.text)
  const rest = fx.filter(f => f.t !== 'toast')
  if (rest.length) void runEffects($, rest).catch((err: unknown) => logOnce($, err))
}

function say($: any, text: string) {
  const t = (testMode ? '[test] ' : '') + text
  $.ui.toast(t, { timeoutMs: 9000 })
  $.ui.log(PREFIX + t)
}

function sync($: any) {
  if (needsHeartbeat(S as State)) {
    timer ??= $.clock.every(HEARTBEAT_MS, () => void tick($).catch((err: unknown) => logOnce($, err)))
  } else if (timer) {
    timer.cancel()
    timer = undefined
  }
}

async function tick($: any) {
  await ensure($)
  const now = await $.clock.now()
  const usage = await readUsage($)
  $.ui.status(statusLine(S as State, usage, now))
  await dispatch($, { type: 'tick', now, usage })
  await publish($, usage, now)
}

async function runEffects($: any, list: Fx[]) {
  for (const f of list) {
    try {
      if (f.t === 'abort') {
        if (turnId) await $.turn.abort({ turnId })
      } else if (f.t === 'compact') {
        await doCompact($, f.instructions)
      } else if (f.t === 'submit') {
        await doSubmit($, f.text)
      } else if (f.t === 'fill') {
        await $.prompt.fill({ text: f.text })
      }
    } catch (err) {
      $.ui.log(PREFIX + `${f.t} failed: ${String(err)}`)
    }
  }
}

async function doCompact($: any, instructions: string) {
  let ok = false
  if (testMode && dryActions) {
    $.ui.log(PREFIX + '[dry-run] would compact the conversation now')
    ok = true
  } else {
    // compact rejects while a turn runs; the turn.complete hook that got us
    // here has not returned yet, so retry until the session is idle.
    for (let i = 0; i < 15 && !ok; i++) {
      try {
        const r = await $.session.compact({ instructions })
        ok = !r || !('skip' in r) || r.skip === undefined
        break
      } catch {
        await $.clock.sleep(1000)
      }
    }
  }
  await dispatch($, { type: 'compactDone', now: await $.clock.now(), ok })
}

async function doSubmit($: any, text: string) {
  if (testMode && dryActions) {
    $.ui.log(PREFIX + `[dry-run] would submit: ${text.split('\n')[0]}`)
    $.clock.after(1500, () => void syntheticMeasure($).catch((err: unknown) => logOnce($, err)))
    return
  }
  await claimSlot($)
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const r = await $.prompt.submit({ text })
      if (!r || r.drop === undefined) return
    } catch {
      /* retry */
    }
    await $.clock.sleep(5000)
  }
  await dispatch($, { type: 'submitFailed', now: await $.clock.now(), text })
}

async function syntheticMeasure($: any) {
  const now = await $.clock.now()
  const usage = await readUsage($)
  if (usage) await dispatch($, { type: 'measure', now, usage })
  await saveSim($)
}

async function boot($: any) {
  await ensure($)
  if (booted || !(await watched($))) return
  booted = true
  const now = await $.clock.now()
  const usage = await readUsage($)
  await dispatch($, { type: 'boot', now, usage })
  $.ui.status(statusLine(S as State, usage, now))
  await publish($, usage, now)
}

// ---------- /quota ----------

async function describe($: any): Promise<string> {
  const now = await $.clock.now()
  const usage = await readUsage($)
  const st = S as State
  const r = st.rec
  const lines: string[] = []
  lines.push(`Auto quota management: ${cfg.enabled ? 'ON' : 'OFF'}${testMode ? `  (TEST MODE, ${dryActions ? 'dry-run actions' : 'real actions'})` : ''}`)
  lines.push(`Thresholds: 5-hour ${cfg.threshold}%, weekly ${cfg.weeklyThreshold}% (${cfg.weeklyPolicy}), compact only if context > ${cfg.compactMinContext}%, abort turn at ${cfg.abortThreshold}%, burn-rate ceiling ${cfg.ceiling}%`)
  if (!usage) lines.push('Usage: unavailable right now (no rate-limit reading yet; subscriptions report it after the first response).')
  else {
    for (const w of usage.windows) lines.push(describeWindow(w, now))
    if (usage.contextPercent !== undefined) lines.push(`Context window: ${usage.contextPercent}% (handled by normal compaction, never a quota pause)`)
  }
  const jump = st.deltas.length ? Math.max(...st.deltas) : 0
  lines.push(`Recent largest jump: ${jump.toFixed(1)} pts`)
  lines.push(`State: ${r.phase.toUpperCase()}${r.reason ? ` - ${r.reason}` : ''}`)
  if (r.phase === 'paused' && r.wakeAt) lines.push(`Paused until approximately ${fmtClock(r.wakeAt)} (in ${fmtDur(r.wakeAt - now)}); resume attempts used: ${r.resumeAttempts}/${cfg.maxResumeAttempts}`)
  if (r.compactedAt) lines.push(`Compacted at ${fmtClock(r.compactedAt)}${r.compactFailed ? ' (failed)' : ''}`)
  if (r.task) lines.push(`Task on record: ${r.task.slice(0, 160)}${r.task.length > 160 ? '...' : ''}`)
  return lines.join('\n')
}

async function startSim($: any, what: string, arg?: string): Promise<string> {
  const now = await $.clock.now()
  sim ??= { five: { percent: 10, resetsAt: now + 5 * 3600_000 }, mode: 'ok', failedOnce: false, probeFails: 0, unavailable: false }
  const set = (p: number, ms: number) => {
    sim!.five = { percent: p, resetsAt: now + ms }
    sim!.failedOnce = false
  }
  switch (what) {
    case '80': set(80, 94 * 60_000); break
    case '94': set(94, 94 * 60_000); break
    case 'exhausted': set(100, 90 * 60_000); break
    case 'reset60': set(100, 60_000); break
    case 'clear': set(10, 5 * 3600_000); sim.week = undefined; break
    case 'weekly': sim.week = { percent: 100, resetsAt: now + 3 * 60_000 }; break
    case 'reset-ok': sim.mode = 'ok'; sim.probeFails = 0; break
    case 'reset-fail': sim.mode = 'fail'; sim.failedOnce = false; break
    case 'reset-delay': sim.mode = 'delay'; sim.probeFails = 1; break
case 'ctx': {
      const n = Number(arg)
      sim.ctx = Number.isFinite(n) ? n : undefined
      await saveSim($)
      return sim.ctx === undefined ? 'Simulated context cleared (real value used).' : `Simulated context set to ${sim.ctx}%.`
    }
    case 'unavailable': sim.unavailable = !sim.unavailable; break
    case 'restart': {
      timer?.cancel()
      timer = undefined
      S = null
      loading = undefined
      booted = false
      turnId = undefined
      await boot($)
      return 'Simulated restart: in-memory state dropped and reloaded from the store.'
    }
    default:
      return 'sim: ctx N | 80 | 94 | exhausted | reset60 | weekly | reset-ok | reset-fail | reset-delay | unavailable | clear | restart'
  }
  await saveSim($)
  if (['80', '94', 'exhausted', 'reset60', 'weekly', 'clear'].includes(what)) await syntheticMeasure($)
  return `sim ${what} applied. Five-hour: ${sim.five.percent}% (resets ${fmtClock(sim.five.resetsAt)}), mode ${sim.mode}${sim.unavailable ? ', usage unavailable' : ''}.`
}

async function command($: any, args: string): Promise<string> {
  const [cmd = 'status', a, b] = args.split(/\s+/)
  const now = await $.clock.now()
  switch (cmd.toLowerCase()) {
    case '':
    case 'status': return describe($)
    case 'on':
    case 'off':
      cfg.enabled = cmd === 'on'
      if (!cfg.enabled) await dispatch($, { type: 'cancel', now })
      await saveCfg($)
      return `Automatic quota management ${cfg.enabled ? 'enabled' : 'disabled'}.`
    case 'threshold':
    case 'weekly': {
      const n = Number(a)
      if (!Number.isFinite(n) || n < 50 || n > 100) return `Usage: /quota ${cmd} <50-100>`
      if (cmd === 'threshold') cfg.threshold = n
      else cfg.weeklyThreshold = n
      await saveCfg($)
      return `${cmd === 'threshold' ? '5-hour' : 'Weekly'} threshold set to ${n}%.`
    }
    case 'pause': {
      const m = a ? Number(a) : 2
      if (!Number.isFinite(m) || m < 0.1) return 'Usage: /quota pause [minutes]'
      await dispatch($, { type: 'forcePause', now, minutes: m })
      return `Forced pause requested for ${m} minute(s)${testMode && dryActions ? ' (dry-run: no real compaction)' : ' (real compaction will run)'}.`
    }
    case 'cancel':
      await dispatch($, { type: 'cancel', now })
      return 'Cancel processed.'
    case 'resume':
      await dispatch($, { type: 'resume', now })
      return 'Resume processed.'
    case 'test': {
      if (a === 'on' || a === 'off') {
        testMode = a === 'on'
        await saveCfg($)
        return `Test mode ${testMode ? 'ON: usage is simulated (/quota sim ...)' : 'OFF: real usage'}.`
      }
      if (a === 'actions' && (b === 'real' || b === 'dry')) {
        dryActions = b === 'dry'
        await saveCfg($)
        return `Test-mode actions: ${b}.`
      }
      return 'Usage: /quota test on|off  or  /quota test actions real|dry'
    }
    case 'ctx':
    case 'legend':
      if (a === 'close') {
        await $.ui.close({ id: PANE })
        return 'Context pane closed.'
      }
      await publish($, await readUsage($), now)
      await $.ui.open({ id: PANE, title: 'Context' })
      return 'Context pane opened (each category has its own colour, largest first).'
    case 'ctxmin': {
      const n = Number(a)
      if (!Number.isFinite(n) || n < 0 || n > 100) return 'Usage: /quota ctxmin <0-100>'
      cfg.compactMinContext = n
      await saveCfg($)
      return `At the quota threshold, compaction now happens only when context is above ${n}%; otherwise it just waits for the reset.`
    }
    case 'sim':
      if (!testMode) return 'Turn on test mode first: /quota test on'
return startSim($, a ?? '', b)
    default:
      return 'Commands: status | on | off | threshold N | weekly N | pause [min] | cancel | resume | test on|off | test actions real|dry | sim <scenario>'
  }
}

async function runQuota($: any, e: { args: string }) {
  if (!(await usable($))) return { text: PREFIX + 'not available (could not load saved state).' }
  return { text: await command($, e.args.trim()) }
}

export const register: Register = (on, opts) => {
  options = opts

  // ---------- hooks (every one fails open) ----------

  on('session.start', async ($, e, next) => {
    try {
      await registerCommand($)
      await boot($)
      void $.ui.open({ id: PANE, title: 'Context' })
    } catch (err) {
      logOnce($, err)
    }
    return next(e)
  })

  // a UI attaching after start (Desktop attaches late): run the startup check then
  on('session.attach', async ($, e, next) => {
    try {
      await boot($)
    } catch (err) {
      logOnce($, err)
    }
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    if (await usable($)) {
      try {
        const now = await $.clock.now()
        const usage = testMode ? await readUsage($) : mapUsage(e)
        if (usage && usage.windows.length) {
          await dispatch($, { type: 'measure', now, usage })
          $.ui.status(statusLine(S as State, usage, now))
          await publish($, usage, now)
        }
      } catch (err) {
        logOnce($, err)
      }
    }
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    turnId = e.turnId
    try {
      await dispatch($, { type: 'turnStart' })
    } catch (err) {
      logOnce($, err)
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId === undefined) {
      turnId = undefined
      try {
        // detached: this hook must return before a compaction can run
        void dispatch($, { type: 'turnComplete', now: await $.clock.now(), reason: e.reason }).catch((err: unknown) => logOnce($, err))
      } catch (err) {
        logOnce($, err)
      }
    }
    return r
  })

  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind === 'plugin' || !(await usable($))) return next(e)
    try {
      const isUser = USER_KINDS.includes(e.origin.kind)
      if (!isUser && cfg.enabled && blocksAutomation(S as State)) {
        return { drop: PREFIX + 'paused for a usage limit; automatic prompts are held.' }
      }
      lastText = e.text
      await dispatch($, { type: 'userPrompt', now: await $.clock.now(), text: e.text, isUser })
    } catch (err) {
      logOnce($, err)
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('session.compact', async ($, e, next) => {
    const r = await next(e)
    try {
      if (e.trigger !== 'precompute' && r && r.skip === undefined && (await usable($))) {
        // our own compaction is reported by doCompact; this catches everyone else's
        if ((S as State).rec.phase !== 'compacting') {
          await dispatch($, { type: 'compactDone', now: await $.clock.now(), ok: true, external: true })
        }
      }
    } catch (err) {
      logOnce($, err)
    }
    return r
  }).catch(($, e, next) => next(e))

  on('tool.call', async ($, e, next) => {
    try {
      if ((await usable($)) && cfg.enabled && (S as State).rec.phase === 'paused') {
        return { deny: PREFIX + 'paused until the usage limit resets.' }
      }
    } catch (err) {
      logOnce($, err)
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!(await usable($))) return next(e)
    if (e.props.hasSurvey) return next(e)
    const v = await read($, bar)
    const { Box, Text } = $.ui.resolve(e)
    const Svg = (e.surface !== 'terminal' ? ($.ui.resolve(e) as any).Svg : undefined) as any
    if (!v) {
      return (
        <Box>
          <Text dimColor>quota-guard · waiting for first usage reading</Text>
        </Box>
      )
    }
    const cols = e.props.bodyColumns
    const tier = cols >= 100 ? 'full' : cols >= 64 ? 'mid' : 'min'
    const T = ({ children, ...rest }: any) => (
      <Text wrap="truncate" {...rest}>
        {children}
      </Text>
    )
    const meter = (pct: number, n: number) => {
      const f = Math.max(0, Math.min(n, Math.round((pct / 100) * n)))
      return (
        <T>
          <Text color={tone(pct)}>{'▰'.repeat(f)}</Text>
          <Text dimColor>{'▱'.repeat(n - f)}</Text>
        </T>
      )
    }
    const n = tier === 'min' ? 5 : 10
    const seg = (name: string, long: string, pct?: number, left?: string, at?: string) => {
      if (pct === undefined) return null
      return (
        <Box gap={1} flexShrink={0}>
          <T dimColor>{tier === 'full' ? long : name}</T>
          {meter(pct, n)}
          <T bold>{Math.round(pct)}%</T>
          {left ? <T dimColor>{tier === 'full' && at ? `${at} · ${left.replace(/ /g, '')}` : left.replace(/ /g, '')}</T> : null}
        </Box>
      )
    }
    const parts = [...(v.parts ?? [])].filter(x => x.pct > 0).sort((x, y) => y.pct - x.pct)
    const segs = parts.length
      ? parts.map((x, i) => ({ pct: x.pct, color: colorAt(i) }))
      : v.ctx !== undefined
        ? [{ pct: v.ctx, color: tone(v.ctx) }]
        : []
    const ctx =
      v.ctx === undefined ? null : (
        <Box gap={1} flexShrink={0}>
          <T dimColor>ctx</T>
          {Svg
            ? ctxPill(Svg, segs.map((sg, i) => ({ pct: sg.pct, hex: parts.length ? hexAt(i) : sg.color === 'red' ? hexAt(4) : sg.color === 'yellow' ? hexAt(2) : hexAt(0) })), tier === 'min' ? 70 : tier === 'mid' ? 110 : 150, 8, v.ctxMin)
            : ctxBar(Box, segs, tier === 'min' ? 8 : tier === 'mid' ? 14 : 20)}
          <T bold>{Math.round(v.ctx)}%</T>
        </Box>
      )
    const alert = !!v.note || v.phase !== 'idle' || testMode
    const state = v.note ?? (v.phase === 'idle' ? undefined : v.phase)
    return (
      <Box gap={3}>
        {seg('5h', '5h session', v.five, v.fiveReset, v.fiveAt)}
        {seg('7d', '7d week', v.week, v.weekReset, v.weekAt)}
        {ctx}
        {alert ? (
          <T color="yellow">
            {testMode ? '[test] ' : ''}
            {state ?? ''}
          </T>
        ) : null}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    if (!(await usable($))) return next(e)
    const d = await read($, detail)
    const { Box, Text } = $.ui.resolve(e)
    const Svg = (e.surface !== 'terminal' ? ($.ui.resolve(e) as any).Svg : undefined) as any
    const barState = await read($, bar)
    const w = Math.max(10, Math.min(36, e.props.bodyColumns - 4))
    if (!d) return <Text dimColor>Waiting for a context reading…</Text>
    const T = ({ children, ...rest }: any) => (
      <Text wrap="truncate" {...rest}>
        {children}
      </Text>
    )
    const win = d.window || 1
    const ranked = d.categories.filter(c => c.kind === 'used' && c.tokens > 0).sort((x, y) => y.tokens - x.tokens)
    const row = (color: string | undefined, name: string, tokens: number, rank?: number) => (
      <Box gap={1}>
        {Svg && rank !== undefined ? swatch(Svg, hexAt(rank)) : <T color={color} dimColor={!color}>■</T>}
        <Box flexGrow={1}>
          <T>{name}</T>
        </Box>
        <T>{fmtTok(tokens)}</T>
        <T dimColor>{((tokens / win) * 100).toFixed(1)}%</T>
      </Box>
    )
    const heading = (t: string) => (
      <Box marginTop={1}>
        <T bold>{t}</T>
      </Box>
    )
    const sub = (items: { name: string; tokens: number }[]) =>
      items.map(i => (
        <Box gap={1} paddingLeft={2}>
          <Box flexGrow={1}>
            <T dimColor>{i.name}</T>
          </Box>
          <T dimColor>{fmtTok(i.tokens)}</T>
        </Box>
      ))
    const free = d.categories.find(c => c.kind === 'free')
    const buffer = d.categories.find(c => c.kind === 'buffer')
    const deferred = d.categories.filter(c => c.kind === 'deferred')
    return (
      <Box flexDirection="column" paddingX={1}>
        <T bold>
          Context · {fmtTok(d.total)} / {fmtTok(win)} · {Math.round(d.percent)}%
        </T>
        <T dimColor>{d.model}</T>
        <Box marginTop={1}>
          {Svg
            ? ctxPill(Svg, ranked.map((c, i) => ({ pct: (c.tokens / win) * 100, hex: hexAt(i) })), Math.max(120, Math.min(320, e.props.bodyColumns * 7)), 10, barState?.ctxMin)
            : ctxBar(Box, ranked.map((c, i) => ({ pct: (c.tokens / win) * 100, color: colorAt(i) })), w)}
        </Box>
        {heading('Where it goes')}
        {ranked.map((c, i) => row(colorAt(i), c.name, c.tokens, i))}
        {free ? row(undefined, 'Free space', free.tokens) : null}
        {buffer ? row(undefined, 'Autocompact buffer', buffer.tokens) : null}
        {d.autoAt ? (
          <T dimColor>
            Auto-compact at {fmtTok(d.autoAt)} ({fmtTok(Math.max(0, d.autoAt - d.total))} to go)
          </T>
        ) : (
          <T dimColor>Auto-compact is off</T>
        )}
        {d.memory.length ? heading('Memory files') : null}
        {sub(d.memory.map(m => ({ name: m.path, tokens: m.tokens })))}
        {d.mcp.length ? heading('MCP servers') : null}
        {sub(d.mcp.map(m => ({ name: m.server, tokens: m.tokens })))}
        {d.agents.length ? heading('Agents') : null}
        {sub(d.agents)}
        {d.skills ? heading(`Skills · ${d.skills.count}/${d.skills.total} listed · ${fmtTok(d.skills.tokens)}`) : null}
        {d.skills ? sub(d.skills.top) : null}
        {deferred.length ? heading('Loaded on demand (not in window)') : null}
        {sub(deferred.map(c => ({ name: c.name, tokens: c.tokens })))}
        {d.api ? heading('Last response') : null}
        {d.api ? (
          <T dimColor>
            in {fmtTok(d.api.input ?? 0)} · cache read {fmtTok(d.api.cacheRead ?? 0)} · cache write {fmtTok(d.api.cacheWrite ?? 0)} · out {fmtTok(d.api.output ?? 0)}
          </T>
        ) : null}
      </Box>
    )
  })

  on('session.end', ($, e, next) => {
    timer?.cancel()
    timer = undefined
    return next(e)
  })

  on('command.run', { command: 'quota' }, runQuota).catch(() => ({ text: PREFIX + 'internal error; see the debug log.' }))
  on('command.run', { command: 'quota-guard' }, runQuota).catch(() => ({ text: PREFIX + 'internal error; see the debug log.' }))
}

files.hooks/core.ts:
// Pure quota state machine. No engine imports: the adapter (register.ts) feeds
// it events and executes the effects it returns, so everything here is
// unit-testable with plain values.

export type Phase = 'idle' | 'armed' | 'compacting' | 'paused' | 'resuming' | 'stopped'

export const FIVE = 'five_hour'
export const WEEK = 'seven_day'

export type Win = { kind: string; percent: number; resetsAt?: number }
export type Usage = { windows: Win[]; contextPercent?: number }

export type Config = {
  enabled: boolean
  threshold: number // 5-hour compaction/pause threshold, %
  weeklyThreshold: number // weekly threshold, %
  abortThreshold: number // abort the running turn at/above this, %
  ceiling: number // burn-rate ceiling: pause if pct + predicted next jump >= this
  burnMultiplier: number
  graceSec: number // wait this long after the reported reset before re-checking
  maxResumeAttempts: number
  weeklyPolicy: 'pause' | 'notify'
  notifyAt: number // one-off heads-up toast at this %, 0 = off
  compactMinContext: number // compact before pausing only if context is above this %
}

export const DEFAULTS: Config = {
  enabled: true,
  threshold: 94,
  weeklyThreshold: 97,
  abortThreshold: 98,
  ceiling: 99,
  burnMultiplier: 1.5,
  graceSec: 30,
  maxResumeAttempts: 5,
  weeklyPolicy: 'pause',
  notifyAt: 80,
  compactMinContext: 30,
}

export type Rec = {
  phase: Phase
  reason?: string
  kinds: string[]
  expectedReset?: number
  wakeAt?: number
  task: string
  pausedAt?: number
  compactedAt?: number
  compactFailed?: boolean
  usage: Win[]
  resumeAttempts: number
  delayCount: number
  lastResumeAt?: number
  abortRequested?: boolean
}

export type State = {
  v: 1
  rec: Rec
  busy: boolean
  deltas: number[] // recent 5-hour jumps per measurement, for burn-rate
  last?: { pct: number; resetsAt?: number }
  notified: string[]
  ctx?: number // last known context-window fill, %
}

export type Ev =
  | { type: 'measure'; now: number; usage: Usage }
  | { type: 'turnStart' }
  | { type: 'turnComplete'; now: number; reason: string }
  | { type: 'userPrompt'; now: number; text: string; isUser: boolean }
  | { type: 'compactDone'; now: number; ok: boolean; external?: boolean }
  | { type: 'tick'; now: number; usage: Usage | null }
  | { type: 'boot'; now: number; usage: Usage | null }
  | { type: 'submitFailed'; now: number; text: string }
  | { type: 'forcePause'; now: number; minutes: number }
  | { type: 'cancel'; now: number }
  | { type: 'resume'; now: number }

export type Fx =
  | { t: 'toast'; text: string }
  | { t: 'abort' }
  | { t: 'compact'; instructions: string }
  | { t: 'submit'; text: string }
  | { t: 'fill'; text: string }

export type Result = { state: State; fx: Fx[] }

export const RESUME_PROMPT =
  'Usage window has reset. Continue the previous task from the compacted context and persisted recovery state. Do not restart completed work.'

const BACKOFF_SEC = [60, 120, 300, 600, 900]
const RESUME_WATCHDOG_MS = 180_000

export function emptyRec(task = ''): Rec {
  return { phase: 'idle', kinds: [], task, usage: [], resumeAttempts: 0, delayCount: 0 }
}

export function initialState(): State {
  return { v: 1, rec: emptyRec(), busy: false, deltas: [], notified: [] }
}

// ---------- formatting ----------

const pad = (n: number) => (n < 10 ? '0' + n : String(n))

export function fmtClock(ms: number): string {
  const d = new Date(ms)
  return `${pad(d.getHours())}:${pad(d.getMinutes())}`
}

export function fmtDur(ms: number): string {
  const m = Math.max(0, Math.round(ms / 60000))
  if (m < 1) return '<1m'
  const h = Math.floor(m / 60)
  if (h >= 24) return `${Math.floor(h / 24)}d ${h % 24}h`
  return h > 0 ? `${h}h ${pad(m % 60)}m`.replace(/ 0(\d)m/, ' $1m') : `${m}m`
}

const label = (kind: string) => (kind === FIVE ? '5-hour' : kind === WEEK ? 'Weekly' : kind)

export function describeWindow(w: Win, now: number): string {
  const reset = w.resetsAt === undefined ? '' : w.resetsAt <= now ? ', reset time passed' : `, resets in ${fmtDur(w.resetsAt - now)}`
  return `${label(w.kind)} usage: ${Math.round(w.percent)}%${reset}`
}

// ---------- helpers ----------

const clone = (s: State): State => JSON.parse(JSON.stringify(s))

function limitFor(kind: string, cfg: Config): number | undefined {
  if (kind === FIVE) return cfg.threshold
  if (kind === WEEK) return cfg.weeklyPolicy === 'pause' ? cfg.weeklyThreshold : undefined
  return undefined
}

export function predictedJump(s: State, cfg: Config): number {
  const m = s.deltas.length ? Math.max(...s.deltas) : 0
  return Math.min(25, m * cfg.burnMultiplier)
}

function breaches(u: Usage, s: State, cfg: Config): Win[] {
  const out: Win[] = []
  for (const w of u.windows) {
    const lim = limitFor(w.kind, cfg)
    if (lim === undefined) continue
    if (w.percent >= lim || (w.kind === FIVE && w.percent + predictedJump(s, cfg) >= cfg.ceiling)) out.push(w)
  }
  return out
}

const backoffMs = (n: number) => (BACKOFF_SEC[Math.min(n, BACKOFF_SEC.length - 1)] ?? 900) * 1000

export function blocksAutomation(s: State): boolean {
  return s.rec.phase === 'paused' || s.rec.phase === 'stopped' || s.rec.phase === 'compacting'
}

export function compactInstructions(task: string): string {
  return (
    'A usage-limit pause is about to start and work will resume automatically afterwards. ' +
    'In the summary, state verbatim the current task' +
    (task ? ` ("${task.slice(0, 600)}")` : '') +
    ', what is already done, what remains, and the exact next step. Do not restart completed work.'
  )
}

export function resumePrompt(r: Rec): string {
  const bits = [RESUME_PROMPT]
  if (r.task) bits.push(`Task before the pause: ${r.task.slice(0, 1500)}`)
  return bits.join('\n\n')
}

// ---------- the machine ----------

export function step(s0: State, ev: Ev, cfg: Config): Result {
  const s = clone(s0)
  const fx: Fx[] = []
  const toast = (text: string) => fx.push({ t: 'toast', text })
  const r = s.rec

  const settle = (task = r.task) => {
    s.rec = emptyRec(task)
  }

  const shouldCompact = () => s.ctx === undefined || s.ctx > cfg.compactMinContext

  const compactOrPause = (now: number) => {
    if (shouldCompact()) startCompact()
    else {
      r.compactedAt = undefined
      enterPause(now)
    }
  }

  const startCompact = () => {
    r.phase = 'compacting'
    fx.push({ t: 'compact', instructions: compactInstructions(r.task) })
  }

  const enterPause = (now: number) => {
    r.phase = 'paused'
    r.pausedAt = now
    const grace = cfg.graceSec * 1000
    r.wakeAt = r.expectedReset === undefined ? now + backoffMs(r.delayCount) : Math.max(r.expectedReset + grace, now + 5000)
    if (r.compactFailed) toast('Compaction failed; pausing anyway.')
    toast(`Paused until approximately ${fmtClock(r.wakeAt)}.`)
  }

  const arm = (now: number, wins: Win[], all: Usage | null, reasonOverride?: string) => {
    const resets = wins.map(w => w.resetsAt).filter((x): x is number => typeof x === 'number')
    const task = r.task
    const fresh: Rec = {
      ...emptyRec(task),
      phase: 'armed',
      kinds: wins.map(w => w.kind),
      reason: reasonOverride ?? wins.map(w => describeWindow(w, now)).join('; '),
      expectedReset: resets.length ? Math.max(...resets) : undefined,
      usage: all ? all.windows.map(w => ({ ...w })) : wins.map(w => ({ ...w })),
    }
    for (const k of Object.keys(r)) delete (r as Record<string, unknown>)[k]
    Object.assign(r, fresh)
    const top = wins[0]
    if (top) {
      const pct = Math.round(top.percent)
      toast(
        shouldCompact()
          ? `${label(top.kind)} usage reached ${pct}%. Compacting before quota exhaustion.`
          : `${label(top.kind)} usage reached ${pct}%. Context is only ${Math.round(s.ctx ?? 0)}%, so no compaction needed; waiting for the reset.`,
      )
    }
    if (s.busy) {
      if (top && top.percent >= cfg.abortThreshold) {
        r.abortRequested = true
        fx.push({ t: 'abort' })
      }
    } else compactOrPause(now)
  }

  const resumeNow = (now: number, mode: 'confirmed' | 'assumed' | 'forced') => {
    if (r.resumeAttempts >= cfg.maxResumeAttempts) {
      r.phase = 'stopped'
      r.wakeAt = undefined
      toast(`Auto-resume gave up after ${r.resumeAttempts} attempts. Use /quota resume or send a prompt.`)
      return
    }
    r.phase = 'resuming'
    r.resumeAttempts++
    r.lastResumeAt = now
    toast(
      mode === 'confirmed'
        ? 'Usage reset confirmed. Resuming task.'
        : mode === 'assumed'
          ? 'Reset time passed (usage not re-measured yet). Resuming task to verify.'
          : 'Resuming task.',
    )
    fx.push({ t: 'submit', text: resumePrompt(r) })
  }

  const resumeFailed = (now: number, why: string, nextReset?: number) => {
    r.delayCount++
    if (r.resumeAttempts >= cfg.maxResumeAttempts) {
      r.phase = 'stopped'
      r.wakeAt = undefined
      toast(`Auto-resume gave up (${why}). Use /quota resume when the limit has reset.`)
      return
    }
    r.phase = 'paused'
    if (nextReset !== undefined) r.expectedReset = nextReset
    r.wakeAt = Math.max(nextReset !== undefined ? nextReset + cfg.graceSec * 1000 : 0, now + backoffMs(r.delayCount))
    toast(`Resume did not take (${why}). Trying again around ${fmtClock(r.wakeAt)}.`)
  }

  const wake = (now: number, usage: Usage | null) => {
    if (!usage || usage.windows.length === 0) {
      r.delayCount++
      const lateAndBlind = r.delayCount >= 3 && (r.expectedReset === undefined || r.expectedReset <= now)
      if (lateAndBlind) return resumeNow(now, 'assumed')
      r.wakeAt = now + backoffMs(r.delayCount)
      if (r.delayCount === 1) toast('Usage data unavailable; will retry shortly.')
      return
    }
    const limited: number[] = []
    let stale = false
    for (const k of r.kinds) {
      const w = usage.windows.find(x => x.kind === k)
      const lim = limitFor(k, cfg) ?? cfg.threshold
      if (!w) {
        stale = true
        continue
      }
      if (w.percent >= lim) {
        if (w.resetsAt !== undefined && w.resetsAt > now) limited.push(w.resetsAt)
        else stale = true // reading predates the reset; only a fresh response can tell
      }
    }
    if (limited.length) {
      const next = Math.max(...limited)
      const moved = r.expectedReset === undefined || Math.abs(next - r.expectedReset) > 60_000
      r.expectedReset = next
      r.wakeAt = next + cfg.graceSec * 1000
      r.delayCount++
      toast(
        moved
          ? `Quota not reset yet; reset time moved to about ${fmtClock(next)}.`
          : `Quota not reset yet; rechecking around ${fmtClock(r.wakeAt)}.`,
      )
      return
    }
    resumeNow(now, stale ? 'assumed' : 'confirmed')
  }

  const tickLike = (now: number, usage: Usage | null) => {
    if (r.phase === 'paused' && r.wakeAt !== undefined && now >= r.wakeAt) wake(now, usage)
    else if (r.phase === 'resuming' && r.lastResumeAt !== undefined && now - r.lastResumeAt > RESUME_WATCHDOG_MS) {
      resumeFailed(now, 'no response to the resume prompt')
    }
  }

  const evaluate = (now: number, usage: Usage) => {
    const hit = breaches(usage, s, cfg)
    if (hit.length) arm(now, hit, usage)
  }

  switch (ev.type) {
    case 'measure': {
      if (typeof ev.usage.contextPercent === 'number') s.ctx = ev.usage.contextPercent
      if (!cfg.enabled) break
      const u = ev.usage
      const five = u.windows.find(w => w.kind === FIVE)
      if (five) {
        const sameWindow = s.last && Math.abs((s.last.resetsAt ?? 0) - (five.resetsAt ?? 0)) < 120_000
        if (sameWindow && s.last && five.percent > s.last.pct) {
          s.deltas.push(five.percent - s.last.pct)
          s.deltas = s.deltas.slice(-5)
        }
        s.last = { pct: five.percent, resetsAt: five.resetsAt }
      }
      const hit = breaches(u, s, cfg)

      if (r.phase === 'resuming') {
        const still = u.windows.filter(w => r.kinds.includes(w.kind) && w.percent >= (limitFor(w.kind, cfg) ?? cfg.threshold) && (w.resetsAt ?? Infinity) > ev.now)
        if (still.length) {
          const next = Math.max(...still.map(w => w.resetsAt ?? ev.now))
          resumeFailed(ev.now, 'quota still exhausted', Number.isFinite(next) ? next : undefined)
        } else {
          const task = r.task
          settle(task)
          toast('Quota reset verified.')
        }
        break
      }
      if (r.phase === 'idle') {
        if (hit.length) {
          arm(ev.now, hit, u)
          break
        }
        if (cfg.notifyAt > 0) {
          for (const w of u.windows) {
            if (limitFor(w.kind, cfg) === undefined && w.kind !== WEEK) continue
            const key = `${w.kind}@${Math.round((w.resetsAt ?? 0) / 60000)}`
            if (w.percent >= cfg.notifyAt && !s.notified.includes(key)) {
              s.notified = [...s.notified, key].slice(-10)
              toast(describeWindow(w, ev.now))
            }
          }
        }
        break
      }
      if (r.phase === 'armed') {
        r.usage = u.windows.map(w => ({ ...w }))
        const worst = hit.reduce((m, w) => Math.max(m, w.percent), 0)
        if (s.busy && !r.abortRequested && worst >= cfg.abortThreshold) {
          r.abortRequested = true
          fx.push({ t: 'abort' })
        }
        break
      }
      if (r.phase === 'paused' || r.phase === 'stopped') {
        const resets = u.windows.filter(w => r.kinds.includes(w.kind) && w.resetsAt !== undefined && w.resetsAt > ev.now).map(w => w.resetsAt as number)
        if (r.phase === 'paused' && resets.length) {
          const next = Math.max(...resets)
          if (r.expectedReset === undefined || Math.abs(next - r.expectedReset) > 60_000) {
            r.expectedReset = next
            r.wakeAt = next + cfg.graceSec * 1000
            toast(`Reset time changed; now paused until approximately ${fmtClock(r.wakeAt)}.`)
          }
        }
      }
      break
    }

    case 'turnStart':
      s.busy = true
      break

    case 'turnComplete': {
      s.busy = false
      if (r.phase === 'armed') {
        if (r.compactedAt !== undefined) enterPause(ev.now)
        else compactOrPause(ev.now)
      } else if (r.phase === 'resuming') {
        if (ev.reason === 'error') resumeFailed(ev.now, 'API error')
        else if (ev.reason === 'aborted') {
          settle()
          toast('Resume turn was interrupted; auto-resume finished.')
        } else {
          settle()
          toast('Quota reset verified.')
        }
      }
      break
    }

    case 'userPrompt': {
      if (!ev.isUser) break
      if (r.phase === 'paused' || r.phase === 'stopped') {
        settle(r.task)
        toast('Auto-resume cancelled: you resumed manually.')
      } else if (r.phase === 'resuming') {
        settle(r.task)
      }
      const t = ev.text.trim()
      if (t && !t.startsWith('/') && (t.length >= 12 || !s.rec.task)) s.rec.task = t.slice(0, 4000)
      break
    }

    case 'compactDone': {
      if (ev.external) {
        if (r.phase === 'armed' || r.phase === 'compacting') {
          r.compactedAt = ev.now
          if (!s.busy) enterPause(ev.now)
        }
        break
      }
      if (r.phase === 'compacting') {
        r.compactedAt = ev.ok ? ev.now : undefined
        r.compactFailed = !ev.ok
        enterPause(ev.now)
      }
      break
    }

    case 'tick':
      tickLike(ev.now, ev.usage)
      break

    case 'boot': {
      s.busy = false
      if (ev.usage && typeof ev.usage.contextPercent === 'number') s.ctx = ev.usage.contextPercent
      if (r.phase === 'compacting' || r.phase === 'armed') {
        if (r.compactedAt !== undefined) {
          enterPause(ev.now)
        } else {
          settle(r.task)
          if (cfg.enabled && ev.usage) evaluate(ev.now, ev.usage)
        }
      } else if (r.phase === 'paused') {
        toast(
          r.wakeAt !== undefined && ev.now < r.wakeAt
            ? `Restored quota pause; checking again around ${fmtClock(r.wakeAt)}.`
            : 'Restored quota pause; reset time has passed, checking now.',
        )
        tickLike(ev.now, ev.usage)
      } else if (r.phase === 'resuming') {
        tickLike(ev.now, ev.usage)
      } else if (r.phase === 'idle' && cfg.enabled && ev.usage) {
        evaluate(ev.now, ev.usage)
      }
      break
    }

    case 'submitFailed': {
      r.phase = 'stopped'
      r.wakeAt = undefined
      fx.push({ t: 'fill', text: ev.text })
      toast('Could not submit the resume prompt automatically. It is in the prompt box: press Enter to continue.')
      break
    }

    case 'forcePause': {
      if (r.phase !== 'idle' && r.phase !== 'stopped') {
        toast(`Already ${r.phase}.`)
        break
      }
      const reset = ev.now + ev.minutes * 60_000
      const task = r.task
      for (const k of Object.keys(r)) delete (r as Record<string, unknown>)[k]
      Object.assign(r, {
        ...emptyRec(task),
        phase: 'armed',
        kinds: ['forced'],
        reason: `forced pause for ${ev.minutes}m (testing)`,
        expectedReset: reset,
      })
      toast(`Forced pause: compacting, then waiting until about ${fmtClock(reset)}.`)
      if (!s.busy) compactOrPause(ev.now)
      break
    }

    case 'cancel': {
      if (r.phase === 'idle') {
        toast('Nothing pending to cancel.')
        break
      }
      r.phase = 'stopped'
      r.wakeAt = undefined
      toast('Auto-resume cancelled. Use /quota resume or send a prompt to continue.')
      break
    }

    case 'resume': {
      if (r.phase === 'paused' || r.phase === 'stopped') {
        r.resumeAttempts = 0
        resumeNow(ev.now, 'forced')
      } else toast('Nothing to resume.')
      break
    }
  }

  return { state: s, fx }
}

export function needsHeartbeat(s: State): boolean {
  return s.rec.phase === 'paused' || s.rec.phase === 'resuming'
}

export function statusLine(s: State, u: Usage | null, now: number): string | undefined {
  const r = s.rec
  if (r.phase === 'paused' && r.wakeAt !== undefined) return `quota pause until ${fmtClock(r.wakeAt)}`
  if (r.phase === 'resuming') return 'quota: resuming'
  if (r.phase === 'stopped') return 'quota: auto-resume held'
  if (r.phase === 'compacting' || r.phase === 'armed') return 'quota: compacting'
  const five = u?.windows.find(w => w.kind === FIVE)
  if (!five) return undefined
  return `5h ${Math.round(five.percent)}%${five.resetsAt && five.resetsAt > now ? ` · ${fmtDur(five.resetsAt - now)}` : ''}`
}

